class BookMyShow:
    def __init__(self, n, m):
        self.m = m
        self.seats = [0] * n

    def gather(self, k, maxRow):
        for r in range(maxRow + 1):                    # linear scan for a fitting row
            if self.m - self.seats[r] >= k:
                col = self.seats[r]
                self.seats[r] += k
                return [r, col]
        return []

    def scatter(self, k, maxRow):
        total = sum(self.m - self.seats[r] for r in range(maxRow + 1))
        if total < k:
            return False
        rem = k
        for r in range(maxRow + 1):
            if rem == 0:
                break
            avail = self.m - self.seats[r]
            take = min(avail, rem)
            self.seats[r] += take
            rem -= take
        return True

