import java.util.*;

class BookMyShow {
    int m;
    int[] seats;
    BookMyShow(int n, int m) { this.m = m; seats = new int[n]; }

    int[] gather(int k, int maxRow) {
        for (int r = 0; r <= maxRow; r++) {              // linear scan for a fitting row
            if (m - seats[r] >= k) {
                int col = seats[r];
                seats[r] += k;
                return new int[]{r, col};
            }
        }
        return new int[]{};
    }

    boolean scatter(int k, int maxRow) {
        long total = 0;
        for (int r = 0; r <= maxRow; r++) total += m - seats[r];
        if (total < k) return false;
        int rem = k;
        for (int r = 0; r <= maxRow && rem > 0; r++) {
            int avail = m - seats[r];
            int take = Math.min(avail, rem);
            seats[r] += take;
            rem -= take;
        }
        return true;
    }
}

