class BookMyShow:
    def __init__(self, n, m):
        self.n = n
        self.m = m
        self.min_tree = [0] * (4 * n)     # min occupied count in range
        self.sum_tree = [0] * (4 * n)     # sum of occupied counts in range

    def _update(self, node, start, end, idx, val):
        if start == end:
            self.min_tree[node] = val
            self.sum_tree[node] = val
            return
        mid = (start + end) // 2
        if idx <= mid:
            self._update(2 * node, start, mid, idx, val)
        else:
            self._update(2 * node + 1, mid + 1, end, idx, val)
        self.min_tree[node] = min(self.min_tree[2 * node], self.min_tree[2 * node + 1])
        self.sum_tree[node] = self.sum_tree[2 * node] + self.sum_tree[2 * node + 1]

    def _query_sum(self, node, start, end, l, r):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return self.sum_tree[node]
        mid = (start + end) // 2
        return self._query_sum(2 * node, start, mid, l, r) + self._query_sum(2 * node + 1, mid + 1, end, l, r)

    def _find_row(self, node, start, end, maxRow, need):
        if start > maxRow or self.min_tree[node] > need:
            return -1
        if start == end:
            return start
        mid = (start + end) // 2
        left = self._find_row(2 * node, start, mid, maxRow, need)
        if left != -1:
            return left
        return self._find_row(2 * node + 1, mid + 1, end, maxRow, need)

    def gather(self, k, maxRow):
        row = self._find_row(1, 0, self.n - 1, maxRow, self.m - k)
        if row == -1:
            return []
        occ = self._query_sum(1, 0, self.n - 1, row, row)
        self._update(1, 0, self.n - 1, row, occ + k)
        return [row, occ]

    def scatter(self, k, maxRow):
        total_free = (maxRow + 1) * self.m - self._query_sum(1, 0, self.n - 1, 0, maxRow)
        if total_free < k:
            return False
        rem = k
        r = 0
        while rem > 0:
            occ = self._query_sum(1, 0, self.n - 1, r, r)
            avail = self.m - occ
            if avail > 0:
                take = min(avail, rem)
                self._update(1, 0, self.n - 1, r, occ + take)
                rem -= take
            r += 1
        return True

