class BookMyShow {
    int n, m;
    int[] minTree, sumTree;

    BookMyShow(int n, int m) {
        this.n = n; this.m = m;
        minTree = new int[4 * n];
        sumTree = new int[4 * n];
    }

    void update(int node, int start, int end, int idx, int val) {
        if (start == end) { minTree[node] = val; sumTree[node] = val; return; }
        int mid = (start + end) / 2;
        if (idx <= mid) update(2 * node, start, mid, idx, val);
        else update(2 * node + 1, mid + 1, end, idx, val);
        minTree[node] = Math.min(minTree[2 * node], minTree[2 * node + 1]);
        sumTree[node] = sumTree[2 * node] + sumTree[2 * node + 1];
    }

    long querySum(int node, int start, int end, int l, int r) {
        if (r < start || end < l) return 0;
        if (l <= start && end <= r) return sumTree[node];
        int mid = (start + end) / 2;
        return querySum(2 * node, start, mid, l, r) + querySum(2 * node + 1, mid + 1, end, l, r);
    }

    int findRow(int node, int start, int end, int maxRow, int need) {
        if (start > maxRow || minTree[node] > need) return -1;
        if (start == end) return start;
        int mid = (start + end) / 2;
        int left = findRow(2 * node, start, mid, maxRow, need);
        if (left != -1) return left;
        return findRow(2 * node + 1, mid + 1, end, maxRow, need);
    }

    int[] gather(int k, int maxRow) {
        int row = findRow(1, 0, n - 1, maxRow, m - k);
        if (row == -1) return new int[]{};
        int occ = (int) querySum(1, 0, n - 1, row, row);
        update(1, 0, n - 1, row, occ + k);
        return new int[]{row, occ};
    }

    boolean scatter(int k, int maxRow) {
        long totalFree = (long) (maxRow + 1) * m - querySum(1, 0, n - 1, 0, maxRow);
        if (totalFree < k) return false;
        int rem = k, r = 0;
        while (rem > 0) {
            int occ = (int) querySum(1, 0, n - 1, r, r);
            int avail = m - occ;
            if (avail > 0) {
                int take = Math.min(avail, rem);
                update(1, 0, n - 1, r, occ + take);
                rem -= take;
            }
            r++;
        }
        return true;
    }
}

